import fs from 'node:fs';
// Candidate lexical senses, never approved ASL equivalences or sentence plans.
const groups={
 travel:{airplane:['aircraft','A fixed-wing aircraft, not the action of flying.'],bicycle:['pedal-vehicle','A two-wheel pedal vehicle.'],boat:['watercraft','A boat or small watercraft.'],bridge:['physical-bridge','A physical structure crossing an obstacle.'],city:['urban-place','A city or urban municipality.'],road:['roadway','A road for travel.'],travel:['travel-action','Travel between places; not every directional or inflected realization.'],vacation:['holiday-break','A vacation or holiday break from usual activity.'],ticket:['admission-pass','An admission or travel ticket; not a legal citation.'],restaurant:['dining-place','A place serving meals to customers.']},
 food:{bottle:['container','A bottle-shaped container.'],bowl:['food-container','A bowl used as a container.'],bread:['baked-food','Bread as food.'],butter:['dairy-spread','Butter as a food spread.'],cheese:['dairy-food','Cheese as food.'],cup:['drinking-vessel','A cup used for drinking; not a measurement or trophy.'],grapes:['fruit','Grapes as fruit.'],lemon:['citrus-fruit','A lemon fruit.'],milk:['dairy-drink','Milk as a drink; not the milking action.'],orange:['citrus-fruit','An orange fruit; distinguish colour before approval.'],plate:['dish','A plate used for food.'],salad:['prepared-food','A salad dish.'],salt:['seasoning','Salt used as seasoning.'],soda:['soft-drink','A carbonated soft drink.'],spoon:['eating-utensil','A spoon used for eating.']},
 people:{friend:['friendship-person','A friend in a personal relationship.'],interpreter:['language-interpreter','A person interpreting between languages; not a software interpreter.'],person:['human-individual','An individual human being.'],waiter:['restaurant-worker','A restaurant server; not the verb wait.'],meeting:['gathering','A meeting or organized gathering.']},
 education:{college:['educational-institution','A college institution.'],english:['english-language','The English language; not an automatic ASL output-language switch.'],keyboard:['computer-keyboard','A computer keyboard; not a musical keyboard.'],language:['human-language','A human language.'],laptop:['portable-computer','A laptop computer.'],learn:['learning-action','Learn information or a skill.'],newspaper:['news-publication','A newspaper publication.'],pencil:['writing-instrument','A pencil used for writing.'],picture:['image','A picture or image.'],science:['scientific-study','Science as a field of study.'],study:['study-action','Study or review learning material.'],university:['educational-institution','A university institution.'],word:['lexical-unit','A word as a language unit.']},
 communication:{email:['electronic-message','An email message or electronic-mail communication; source realization requires review.'],internet:['computer-network','The Internet as a computer network.'],name:['personal-name-label','A person name label, without supplying a name sign or fingerspelling.'],send:['send-action','Send something; participants and direction are not inferred.'],share:['sharing-action','Share something with others; participants need contextual review.'],talk:['communication-action','Talk or converse; not a complete signed conversation.'],telephone:['telephone-device','A telephone device or telephone communication; exact source sense needs review.'],together:['jointly','Together or jointly, without asserting a sentence construction.']},
 home:{blanket:['bed-cover','A blanket used as a cover.'],box:['container','A box-shaped container.'],glasses:['eyeglasses','Eyeglasses worn for vision; not drinking glasses.'],hat:['headwear','A hat worn on the head.'],house:['dwelling','A house as a dwelling.'],jacket:['outerwear','A jacket worn as outerwear.'],key:['lock-key','A physical key for a lock; not a keyboard or musical key.'],lamp:['lighting-device','A lamp used for lighting.'],napkin:['table-cloth','A napkin used at a table.'],socks:['footwear','Socks worn on the feet.'],sofa:['seating-furniture','A sofa or couch used for seating.'],stairs:['steps-structure','A set of stairs in a building.']},
 nature:{animal:['nonhuman-animal','An animal in the ordinary nonhuman sense.'],cat:['domestic-animal','A domestic cat.'],dog:['domestic-animal','A domestic dog.'],duck:['waterbird','A duck as an animal, not lowering the head.'],flower:['plant-blossom','A flower or blossom.'],forest:['woodland','A forest or woodland area.'],horse:['animal','A horse as an animal.'],rabbit:['animal','A rabbit as an animal.'],rain:['precipitation','Rain as weather.'],river:['watercourse','A river or watercourse; not a financial bank.'],star:['celestial-body','A star in the sky; not a famous person.'],sun:['celestial-body','The Sun.'],tree:['woody-plant','A tree as a plant.'],weather:['atmospheric-conditions','Weather or atmospheric conditions.']},
 description:{blue:['colour','The colour blue.'],green:['colour','The colour green.'],pink:['colour','The colour pink.'],purple:['colour','The colour purple.'],red:['colour','The colour red.'],small:['small-size','Small physical size; not every classifier/degree construction.'],white:['colour','The colour white.'],yellow:['colour','The colour yellow.']},
 time:{birthday:['birth-anniversary','A birthday or anniversary of birth.'],monday:['weekday','Monday as a day of the week.'],summer:['season','Summer as a season.'],week:['calendar-period','A week; numerical inflection is not inferred.'],year:['calendar-period','A year; numerical inflection is not inferred.']}
};
const library=JSON.parse(fs.readFileSync('web/vocabulary-manifest.json'));
export const expansionRows=Object.entries(groups).flatMap(([category,items])=>Object.entries(items).map(([word,[sense,definition]])=>({word,sense,definition,category,reference:`https://www.lifeprint.com/asl101/pages-signs/${word[0]}/${word}.htm`})));
export const proposedRows=expansionRows.filter(row=>!library.concepts.some(c=>c.aliases.some(a=>a.text===row.word)));
if(process.argv.includes('--list'))console.log(proposedRows.map(row=>row.word).join(','));
if(process.argv.includes('--write')){
  const inventory=JSON.parse(fs.readFileSync('asset-downloads/expansion-20261018/inventory.json'));
  const references=[...JSON.parse(fs.readFileSync('asset-downloads/expansion-research-20261018/reference-checks.json')),...JSON.parse(fs.readFileSync('docs/research/expansion-public-reference-checks-20261018.json'))];
  const available=new Set(inventory.samples.map(s=>s.file.slice(9,-4))),good=new Set(references.filter(r=>r.status===200&&r.aslReference).map(r=>r.word));
  const selected=proposedRows.filter(row=>available.has(row.word)&&good.has(row.word));
  if(selected.length>100)throw Error('Bounded batch exceeded.');
  const conceptProposals=selected.map(row=>({id:`asl.${row.word}.${row.sense}`,signLanguage:'ASL',sense:row.sense,label:row.word[0].toUpperCase()+row.word.slice(1),definition:row.definition,category:row.category,aliases:[row.word],inflections:[],exampleContexts:[],sourceProject:'https://osf.io/mqzyk/',license:'CC-BY-4.0',meaningReference:row.reference}));
  // Proposal aliases are strings; runtime manifest aliases are structured records.
  const records=conceptProposals.map(c=>({id:'3dlex-'+c.aliases[0],word:c.aliases[0],conceptId:c.id,sense:c.sense,signLanguage:'ASL',sourcePath:`asset-downloads/expansion-20261018/${c.aliases[0]}.glb`,variantId:'3dlex-v1-source',variantLabel:'3D-LEX original capture; intended sense and variant await human ASL review',sourceProject:c.sourceProject,archiveURL:'https://osf.io/download/tcnhs/',license:c.license,sourceLanguageVerified:true,meaningReference:c.meaningReference}));
  fs.writeFileSync('imports/asl-expansion-20261018.json',JSON.stringify({schema:'asl-motion-batch/1',id:'asl-expansion-20261018',conceptProposals,entries:records},null,2)+'\n',{flag:'wx'});
  console.log(JSON.stringify({proposed:proposedRows.length,selected:selected.length,excluded:proposedRows.filter(r=>!selected.includes(r)).map(r=>r.word)}));
}
